#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, x, y;
    string s;
    cin >> n >> m >> x >> y >> s;

    int dx = (s[0] == 'U' ? -1 : 1);
    int dy = (s[1] == 'L' ? -1 : 1);

    int remaining = n + m - 2;
    ll distance = 0;

    set<pair<int, int>> visitedPoints;
    set<tuple<int, int, int, int>> visitedStates;

    if (x == 1 || x == n || y == 1 || y == m) {
        visitedPoints.insert({x, y});
        --remaining;
    }

    if (remaining <= 0) {
        cout << 1 << '\n';
        return 0;
    }

    while (true) {
        auto state = make_tuple(x, y, dx, dy);
        if (!visitedStates.insert(state).second) {
            cout << -1 << '\n';
            return 0;
        }

        int step = INT_MAX;
        step = min(step, dx == 1 ? n - x : x - 1);
        step = min(step, dy == 1 ? m - y : y - 1);

        x += dx * step;
        y += dy * step;
        distance += step;

        if (x == 1) dx = 1;
        else if (x == n) dx = -1;

        if (y == 1) dy = 1;
        else if (y == m) dy = -1;

        if (visitedPoints.insert({x, y}).second) {
            --remaining;
            if (remaining == 0) {
                cout << distance + 1 << '\n';
                return 0;
            }
        }
    }
}

