        return static_cast<ll>(px) * (m + 1LL) + py;
    };

    auto stateKey = [&](int px, int py, int vx, int vy) -> ll {
        ll key = positionKey(px, py);
        key = key * 2 + (vx == 1);
        key = key * 2 + (vy == 1);
        return key;
    };

    if (x == 1 || x == n || y == 1 || y == m) {
        visitedPositions.insert(positionKey(x, y));
        --cnt;
    }

    if (cnt <= 0) {
        cout << 1 << '\n';
        return 0;
    }

    while (true) {
        ll state = stateKey(x, y, dx, dy);
        if (!visitedStates.insert(state).second) {
            cout << -1 << '\n';
            return 0;
        }

        int dis = INT_MAX;
        dis = min(dis, dx == 1 ? n - x : x - 1);
        dis = min(dis, dy == 1 ? m - y : y - 1);

